 26	    public Reservation createReservation(String guestName, String guestEmail,
 27	                                        String guestCpf, String companyCnpj, String companyName,
 28	                                        String guestPassport, String guestCountry,
 29	                                        int roomNumber, LocalDate checkIn, LocalDate checkOut,
 30	                                        int guests, String ratePlan) throws SQLException {
 31	        validateIdentification(guestCpf, companyCnpj, companyName, guestPassport, guestCountry);
 32	
 33	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
 34	            throw new ApiException("INVALID_REQUEST", "Check-out date must be after check-in date", 400);
 35	        }
 36	
 37	        if (guests < 1) {
 38	            throw new ApiException("INVALID_REQUEST", "At least 1 guest is required", 400);
 39	        }
 40	
 41	        Room room = roomService.getRoomByNumber(roomNumber);
 42	        if (room == null) {
 43	            throw new ApiException("ROOM_NOT_FOUND", "Room not found", 404);
 44	        }
 45	
 46	        if (guests > room.getCapacity()) {
 47	            throw new ApiException("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity", 422);
 48	        }
 49	
 50	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
 51	            throw new ApiException("ROOM_UNAVAILABLE", "Room is not available for selected dates", 409);
 52	        }
 53	
 54	        long nights = ChronoUnit.DAYS.between(checkIn, checkOut);
 55	
 56	        BigDecimal subtotal = calculateSubtotal(room.getNightlyRate(), (int) nights, checkIn, checkOut);
 57	        BigDecimal discount = calculateDiscount(subtotal, ratePlan);
 58	        BigDecimal total = MoneyUtils.round(subtotal.subtract(discount));
 59	
 60	        try (Connection conn = db.getConnection()) {
 61	            String sql = """
 62	                INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, company_cnpj,
 63	                                        company_name, guest_passport, guest_country, check_in, check_out,
 64	                                        guests, rate_plan, nights, subtotal, discount, total, status, amount_paid)
 65	                VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'PENDING', 0)
 66	            """;
 67	
 68	            try (PreparedStatement pstmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
 69	                pstmt.setInt(1, roomNumber);
 70	                pstmt.setString(2, guestName);
 71	                pstmt.setString(3, guestEmail);
 72	                pstmt.setString(4, guestCpf);
 73	                pstmt.setString(5, companyCnpj);
 74	                pstmt.setString(6, companyName);
 75	                pstmt.setString(7, guestPassport);
 76	                pstmt.setString(8, guestCountry);
 77	                pstmt.setDate(9, java.sql.Date.valueOf(checkIn));
 78	                pstmt.setDate(10, java.sql.Date.valueOf(checkOut));
 79	                pstmt.setInt(11, guests);
 80	                pstmt.setString(12, ratePlan);
 81	                pstmt.setInt(13, (int) nights);
 82	                pstmt.setBigDecimal(14, subtotal);
 83	                pstmt.setBigDecimal(15, discount);
 84	                pstmt.setBigDecimal(16, total);
 85	
 86	                pstmt.executeUpdate();
 87	
 88	                try (ResultSet generatedKeys = pstmt.getGeneratedKeys()) {
 89	                    if (generatedKeys.next()) {
 90	                        long reservationId = generatedKeys.getLong(1);
 91	                        return getReservation(reservationId);
 92	                    }
 93	                }
 94	            }
 95	        }
 96	
 97	        return null;
 98	    }
