100	    public Reservation getReservation(long id) throws SQLException {
101	        try (Connection conn = db.getConnection()) {
102	            String sql = """
103	                SELECT id, room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
104	                       guest_passport, guest_country, check_in, check_out, guests, rate_plan, nights,
105	                       subtotal, discount, total, status, amount_paid, refund
106	                FROM reservations WHERE id = ?
107	            """;
108	
109	            try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
110	                pstmt.setLong(1, id);
111	                try (ResultSet rs = pstmt.executeQuery()) {
112	                    if (rs.next()) {
113	                        return mapReservation(rs);
114	                    }
115	                }
116	            }
117	        }
118	        return null;
119	    }
