121	    public void confirmReservation(long id, BigDecimal amountPaid) throws SQLException {
122	        Reservation res = getReservation(id);
123	        if (res == null) {
124	            throw new ApiException("RESERVATION_NOT_FOUND", "Reservation not found", 404);
125	        }
126	
127	        if (!res.getStatus().equals("PENDING")) {
128	            throw new ApiException("OPERATION_NOT_ALLOWED", "Can only confirm PENDING reservations", 409);
129	        }
130	
131	        try (Connection conn = db.getConnection()) {
132	            String sql = "UPDATE reservations SET status = 'CONFIRMED', amount_paid = ? WHERE id = ?";
133	            try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
134	                pstmt.setBigDecimal(1, amountPaid);
135	                pstmt.setLong(2, id);
136	                pstmt.executeUpdate();
137	            }
138	        }
139	    }
