179	    public void cancelReservation(long id) throws SQLException {
180	        Reservation res = getReservation(id);
181	        if (res == null) {
182	            throw new ApiException("RESERVATION_NOT_FOUND", "Reservation not found", 404);
183	        }
184	
185	        if (!res.getStatus().equals("PENDING") && !res.getStatus().equals("CONFIRMED")) {
186	            throw new ApiException("OPERATION_NOT_ALLOWED", "Can only cancel PENDING or CONFIRMED reservations", 409);
187	        }
188	
189	        BigDecimal refund = BigDecimal.ZERO;
190	        if (res.getStatus().equals("CONFIRMED") && res.getRatePlan().equals("STANDARD")) {
191	            refund = res.getAmountPaid();
192	        }
193	
194	        try (Connection conn = db.getConnection()) {
195	            String sql = "UPDATE reservations SET status = 'CANCELLED', refund = ? WHERE id = ?";
196	            try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
197	                pstmt.setBigDecimal(1, refund);
198	                pstmt.setLong(2, id);
199	                pstmt.executeUpdate();
200	            }
201	        }
202	    }
