204	    public List<Reservation> getReservationsByRoomAndDate(int roomNumber, LocalDate date) throws SQLException {
205	        List<Reservation> reservations = new ArrayList<>();
206	        try (Connection conn = db.getConnection()) {
207	            String sql = """
208	                SELECT id, room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
209	                       guest_passport, guest_country, check_in, check_out, guests, rate_plan, nights,
210	                       subtotal, discount, total, status, amount_paid, refund
211	                FROM reservations
212	                WHERE room_number = ? AND check_in <= ? AND check_out > ? AND status != 'CANCELLED'
213	                ORDER BY check_in
214	            """;
215	
216	            try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
217	                pstmt.setInt(1, roomNumber);
218	                pstmt.setDate(2, java.sql.Date.valueOf(date));
219	                pstmt.setDate(3, java.sql.Date.valueOf(date));
220	
221	                try (ResultSet rs = pstmt.executeQuery()) {
222	                    while (rs.next()) {
223	                        reservations.add(mapReservation(rs));
224	                    }
225	                }
226	            }
227	        }
228	        return reservations;
229	    }
