231	    public List<Reservation> getReservationsByMonthWithPayment(YearMonth yearMonth) throws SQLException {
232	        List<Reservation> reservations = new ArrayList<>();
233	        try (Connection conn = db.getConnection()) {
234	            String sql = """
235	                SELECT id, room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
236	                       guest_passport, guest_country, check_in, check_out, guests, rate_plan, nights,
237	                       subtotal, discount, total, status, amount_paid, refund
238	                FROM reservations
239	                WHERE EXTRACT(YEAR FROM check_in) = ? AND EXTRACT(MONTH FROM check_in) = ?
240	                  AND (status = 'CONFIRMED' OR status = 'CHECKED_IN' OR status = 'CHECKED_OUT' OR (status = 'CANCELLED' AND amount_paid > 0))
241	                ORDER BY check_in, id
242	            """;
243	
244	            try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
245	                pstmt.setInt(1, yearMonth.getYear());
246	                pstmt.setInt(2, yearMonth.getMonthValue());
247	
248	                try (ResultSet rs = pstmt.executeQuery()) {
249	                    while (rs.next()) {
250	                        reservations.add(mapReservation(rs));
251	                    }
252	                }
253	            }
254	        }
255	        return reservations;
256	    }
