258	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) throws SQLException {
259	        try (Connection conn = db.getConnection()) {
260	            String sql = """
261	                SELECT COUNT(*) FROM reservations
262	                WHERE room_number = ? AND check_in < ? AND check_out > ? AND status != 'CANCELLED'
263	            """;
264	
265	            try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
266	                pstmt.setInt(1, roomNumber);
267	                pstmt.setDate(2, java.sql.Date.valueOf(checkOut));
268	                pstmt.setDate(3, java.sql.Date.valueOf(checkIn));
269	
270	                try (ResultSet rs = pstmt.executeQuery()) {
271	                    rs.next();
272	                    return rs.getInt(1) > 0;
273	                }
274	            }
275	        }
276	    }
277	
278	    private BigDecimal calculateSubtotal(BigDecimal nightlyRate, int nights, LocalDate checkIn, LocalDate checkOut) {
279	        BigDecimal total = BigDecimal.ZERO;
280	        LocalDate current = checkIn;
281	
282	        while (current.isBefore(checkOut)) {
283	            BigDecimal rate = nightlyRate;
284	
285	            if (isHighSeason(current)) {
286	                rate = rate.multiply(new BigDecimal("1.20"));
287	            }
288	
289	            rate = MoneyUtils.round(rate);
290	            total = total.add(rate);
291	            current = current.plusDays(1);
292	        }
293	
294	        return MoneyUtils.round(total);
295	    }
296	
297	    private BigDecimal calculateDiscount(BigDecimal subtotal, String ratePlan) {
298	        if ("NON_REFUNDABLE".equals(ratePlan)) {
299	            BigDecimal discount = subtotal.multiply(new BigDecimal("0.15"));
300	            return MoneyUtils.round(discount);
301	        }
302	        return BigDecimal.ZERO;
303	    }
304	
305	    private boolean isHighSeason(LocalDate date) {
306	        int month = date.getMonthValue();
307	        int day = date.getDayOfMonth();
308	
309	        if (month == 7) return true;
310	        if (month == 12) return true;
311	        if (month == 1) return true;
312	        if (month == 2) return day <= 28;
313	
314	        return false;
315	    }
316	
317	    private void validateIdentification(String guestCpf, String companyCnpj, String companyName,
318	                                       String guestPassport, String guestCountry) {
319	        int identificationCount = 0;
320	
321	        if (guestCpf != null && !guestCpf.isEmpty()) identificationCount++;
322	        if (companyCnpj != null && !companyCnpj.isEmpty()) identificationCount++;
323	        if (guestPassport != null && !guestPassport.isEmpty()) identificationCount++;
324	
325	        if (identificationCount != 1) {
326	            throw new ApiException("INVALID_REQUEST", "Exactly one identification method must be provided", 400);
327	        }
328	
329	        if (companyCnpj != null && !companyCnpj.isEmpty() &&
330	            (companyName == null || companyName.isEmpty())) {
331	            throw new ApiException("INVALID_REQUEST", "Company name is required when using CNPJ", 400);
332	        }
333	
334	        if (guestPassport != null && !guestPassport.isEmpty() &&
335	            (guestCountry == null || guestCountry.isEmpty())) {
336	            throw new ApiException("INVALID_REQUEST", "Guest country is required when using passport", 400);
337	        }
338	    }
339	
340	    private Reservation mapReservation(ResultSet rs) throws SQLException {
341	        return new Reservation(
342	            rs.getLong("id"),
343	            rs.getInt("room_number"),
344	            rs.getString("guest_name"),
345	            rs.getString("guest_email"),
346	            rs.getString("guest_cpf"),
347	            rs.getString("company_cnpj"),
348	            rs.getString("company_name"),
349	            rs.getString("guest_passport"),
350	            rs.getString("guest_country"),
351	            rs.getDate("check_in").toLocalDate(),
352	            rs.getDate("check_out").toLocalDate(),
353	            rs.getInt("guests"),
354	            rs.getString("rate_plan"),
355	            rs.getInt("nights"),
356	            rs.getBigDecimal("subtotal"),
357	            rs.getBigDecimal("discount"),
358	            rs.getBigDecimal("total"),
359	            rs.getString("status"),
360	            rs.getBigDecimal("amount_paid"),
361	            rs.getBigDecimal("refund")
362	        );
363	    }
364	}

