204	    }
205	
206	    public static String formatBRL_EN(BigDecimal value) {
207	        if (value == null) {
208	            return null;
209	        }
210	        return String.format("BRL %,d.%02d", value.longValue() / 100, value.longValue() % 100);
211	    }
212	
