  2	
  3	import io.javalin.http.Context;
  4	import com.pousadamareaita.database.Database;
  5	import com.pousadamareaita.service.ReservationService;
  6	import com.pousadamareaita.service.RoomService;
  7	import com.pousadamareaita.service.MessageService;
  8	import com.pousadamareaita.service.DocumentService;
  9	import com.pousadamareaita.model.Reservation;
 10	import com.pousadamareaita.model.Document;
 11	import com.pousadamareaita.exception.ApiException;
 12	import com.fasterxml.jackson.databind.ObjectMapper;
 13	import com.fasterxml.jackson.databind.JsonNode;
 14	
 15	import java.time.LocalDate;
 16	import java.time.format.DateTimeFormatter;
 17	import java.math.BigDecimal;
 18	
 19	public class ReservationHandler {
 20	    private final ReservationService reservationService;
 21	    private final MessageService messageService;
 22	    private final DocumentService documentService;
 23	    private final ObjectMapper mapper = new ObjectMapper();
 24	
 25	    public ReservationHandler(Database db) {
 26	        this.reservationService = new ReservationService(db);
 27	        this.messageService = new MessageService(db);
 28	        this.documentService = new DocumentService(new RoomService(db));
 29	    }
 30	
 31	    public void createReservation(Context ctx) {
 32	        try {
 33	            JsonNode body = mapper.readTree(ctx.body());
 34	
 35	            String guestName = getStringField(body, "guestName");
 36	            String guestEmail = getStringField(body, "guestEmail");
 37	            String guestCpf = getStringField(body, "guestCpf");
 38	            String companyCnpj = getStringField(body, "companyCnpj");
 39	            String companyName = getStringField(body, "companyName");
 40	            String guestPassport = getStringField(body, "guestPassport");
 41	            String guestCountry = getStringField(body, "guestCountry");
 42	
 43	            if (guestName == null || guestEmail == null) {
 44	                throw new ApiException("INVALID_REQUEST", "guestName and guestEmail are required", 400);
 45	            }
 46	
 47	            int roomNumber = getIntField(body, "roomNumber");
 48	            LocalDate checkIn = getDateField(body, "checkIn");
 49	            LocalDate checkOut = getDateField(body, "checkOut");
 50	            int guests = getIntField(body, "guests");
 51	            String ratePlan = getStringField(body, "ratePlan");
 52	
 53	            if (checkIn == null || checkOut == null || ratePlan == null) {
 54	                throw new ApiException("INVALID_REQUEST", "checkIn, checkOut, and ratePlan are required", 400);
 55	            }
 56	
 57	            Reservation reservation = reservationService.createReservation(
 58	                guestName, guestEmail, guestCpf, companyCnpj, companyName, guestPassport, guestCountry,
 59	                roomNumber, checkIn, checkOut, guests, ratePlan
 60	            );
 61	
 62	            ctx.status(201);
 63	            ctx.json(reservation);
 64	        } catch (ApiException e) {
 65	            sendErrorResponse(ctx, e.getCode(), e.getMessage(), e.getStatusCode());
 66	        } catch (Exception e) {
 67	            sendErrorResponse(ctx, "INVALID_REQUEST", e.getMessage(), 400);
 68	        }
 69	    }
 70	
 71	    public void getReservation(Context ctx) {
 72	        try {
 73	            long id = Long.parseLong(ctx.pathParam("id"));
 74	            Reservation reservation = reservationService.getReservation(id);
 75	
 76	            if (reservation == null) {
 77	                throw new ApiException("RESERVATION_NOT_FOUND", "Reservation not found", 404);
 78	            }
 79	
 80	            ctx.json(reservation);
 81	        } catch (ApiException e) {
 82	            sendErrorResponse(ctx, e.getCode(), e.getMessage(), e.getStatusCode());
 83	        } catch (Exception e) {
 84	            sendErrorResponse(ctx, "INVALID_REQUEST", e.getMessage(), 400);
 85	        }
 86	    }
 87	
 88	    public void confirmReservation(Context ctx) {
 89	        try {
 90	            long id = Long.parseLong(ctx.pathParam("id"));
 91	            JsonNode body = mapper.readTree(ctx.body());
 92	
 93	            BigDecimal amountPaid = null;
 94	            if (body.has("amountPaid")) {
