 18	
 19	public class ReportHandler {
 20	    private final ReservationService reservationService;
 21	    private final RoomService roomService;
 22	
 23	    public ReportHandler(Database db) {
 24	        this.reservationService = new ReservationService(db);
 25	        this.roomService = new RoomService(db);
 26	    }
 27	
 28	    public void getOccupancyReport(Context ctx) {
 29	        try {
 30	            String dateStr = ctx.queryParam("date");
 31	            if (dateStr == null || dateStr.isEmpty()) {
 32	                throw new ApiException("INVALID_REQUEST", "date parameter is required", 400);
 33	            }
 34	
 35	            LocalDate date;
 36	            try {
 37	                date = LocalDate.parse(dateStr, DateTimeFormatter.ISO_LOCAL_DATE);
 38	            } catch (Exception e) {
 39	                throw new ApiException("INVALID_REQUEST", "Invalid date format, use YYYY-MM-DD", 400);
 40	            }
 41	
 42	            StringBuilder csv = new StringBuilder();
 43	            csv.append("room,type,reservation,check_in,check_out\n");
 44	
 45	            List<Room> rooms = roomService.getAllRooms();
 46	            int occupiedRooms = 0;
 47	
 48	            for (Room room : rooms) {
 49	                List<Reservation> reservations = reservationService.getReservationsByRoomAndDate(room.getNumber(), date);
 50	
 51	                boolean roomOccupied = false;
 52	                for (Reservation res : reservations) {
 53	                    if (res.getStatus().equals("CONFIRMED") || res.getStatus().equals("CHECKED_IN") || res.getStatus().equals("CHECKED_OUT")) {
 54	                        csv.append(room.getNumber()).append(",");
 55	                        csv.append(room.getType()).append(",");
 56	                        csv.append(res.getId()).append(",");
 57	                        csv.append(res.getCheckIn()).append(",");
 58	                        csv.append(res.getCheckOut()).append("\n");
 59	                        if (!roomOccupied) {
 60	                            occupiedRooms++;
 61	                            roomOccupied = true;
 62	                        }
 63	                    }
 64	                }
 65	            }
 66	
 67	            csv.append("total,").append(occupiedRooms).append("/").append(rooms.size());
 68	
 69	            ctx.contentType("text/csv;charset=utf-8");
 70	            ctx.result(csv.toString());
 71	        } catch (ApiException e) {
 72	            ctx.status(e.getStatusCode());
 73	            ctx.json(new ErrorResponse(e.getCode(), e.getMessage()));
 74	        } catch (Exception e) {
 75	            ctx.status(400);
 76	            ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
 77	        }
 78	    }
 79	
 80	    public void getRevenueReport(Context ctx) {
 81	        try {
 82	            String monthStr = ctx.queryParam("month");
 83	            if (monthStr == null || monthStr.isEmpty()) {
 84	                throw new ApiException("INVALID_REQUEST", "month parameter is required", 400);
 85	            }
 86	
 87	            YearMonth month;
 88	            try {
 89	                month = YearMonth.parse(monthStr, DateTimeFormatter.ofPattern("yyyy-MM"));
 90	            } catch (Exception e) {
 91	                throw new ApiException("INVALID_REQUEST", "Invalid month format, use YYYY-MM", 400);
 92	            }
 93	
 94	            StringBuilder csv = new StringBuilder();
 95	            csv.append("reservation,room,check_in,check_out,status,amount\n");
 96	
 97	            List<Reservation> reservations = reservationService.getReservationsByMonthWithPayment(month);
 98	            BigDecimal total = BigDecimal.ZERO;
 99	
100	            for (Reservation res : reservations) {
101	                BigDecimal money = res.getAmountPaid();
102	                if (res.getRefund() != null) {
103	                    money = money.subtract(res.getRefund());
104	                }
105	
106	                csv.append(res.getId()).append(",");
107	                csv.append(res.getRoomNumber()).append(",");
108	                csv.append(res.getCheckIn()).append(",");
109	                csv.append(res.getCheckOut()).append(",");
110	                csv.append(res.getStatus()).append(",");
111	                csv.append(formatAmount(money)).append("\n");
112	
113	                total = total.add(money);
114	            }
115	
116	            csv.append("total,,,,").append(formatAmount(total));
117	
118	            ctx.contentType("text/csv;charset=utf-8");
119	            ctx.result(csv.toString());
120	        } catch (ApiException e) {
121	            ctx.status(e.getStatusCode());
122	            ctx.json(new ErrorResponse(e.getCode(), e.getMessage()));
123	        } catch (Exception e) {
124	            ctx.status(400);
125	            ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
126	        }
127	    }
128	
129	    private String formatAmount(BigDecimal amount) {
130	        if (amount == null) {
131	            return "0.00";
132	        }
133	        return String.format("%.2f", amount);
134	    }
135	
136	    static class ErrorResponse {
137	        public String error;
138	        public String message;
139	
140	        ErrorResponse(String error, String message) {
141	            this.error = error;
142	            this.message = message;
143	        }
144	    }
