 28	    public void getOccupancyReport(Context ctx) {
 29	        try {
 30	            String dateStr = ctx.queryParam("date");
 31	            if (dateStr == null || dateStr.isEmpty()) {
 32	                throw new ApiException("INVALID_REQUEST", "date parameter is required", 400);
 33	            }
 34	
 35	            LocalDate date;
 36	            try {
 37	                date = LocalDate.parse(dateStr, DateTimeFormatter.ISO_LOCAL_DATE);
 38	            } catch (Exception e) {
 39	                throw new ApiException("INVALID_REQUEST", "Invalid date format, use YYYY-MM-DD", 400);
 40	            }
 41	
 42	            StringBuilder csv = new StringBuilder();
 43	            csv.append("room,type,reservation,check_in,check_out\n");
 44	
 45	            List<Room> rooms = roomService.getAllRooms();
 46	            int occupiedRooms = 0;
 47	
 48	            for (Room room : rooms) {
 49	                List<Reservation> reservations = reservationService.getReservationsByRoomAndDate(room.getNumber(), date);
 50	
 51	                boolean roomOccupied = false;
 52	                for (Reservation res : reservations) {
 53	                    if (res.getStatus().equals("CONFIRMED") || res.getStatus().equals("CHECKED_IN") || res.getStatus().equals("CHECKED_OUT")) {
 54	                        csv.append(room.getNumber()).append(",");
 55	                        csv.append(room.getType()).append(",");
 56	                        csv.append(res.getId()).append(",");
 57	                        csv.append(res.getCheckIn()).append(",");
 58	                        csv.append(res.getCheckOut()).append("\n");
 59	                        if (!roomOccupied) {
 60	                            occupiedRooms++;
 61	                            roomOccupied = true;
 62	                        }
 63	                    }
 64	                }
 65	            }
 66	
 67	            csv.append("total,").append(occupiedRooms).append("/").append(rooms.size());
 68	
 69	            ctx.contentType("text/csv;charset=utf-8");
 70	            ctx.result(csv.toString());
 71	        } catch (ApiException e) {
 72	            ctx.status(e.getStatusCode());
 73	            ctx.json(new ErrorResponse(e.getCode(), e.getMessage()));
 74	        } catch (Exception e) {
 75	            ctx.status(400);
 76	            ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
 77	        }
 78	    }
