 80	    public void getRevenueReport(Context ctx) {
 81	        try {
 82	            String monthStr = ctx.queryParam("month");
 83	            if (monthStr == null || monthStr.isEmpty()) {
 84	                throw new ApiException("INVALID_REQUEST", "month parameter is required", 400);
 85	            }
 86	
 87	            YearMonth month;
 88	            try {
 89	                month = YearMonth.parse(monthStr, DateTimeFormatter.ofPattern("yyyy-MM"));
 90	            } catch (Exception e) {
 91	                throw new ApiException("INVALID_REQUEST", "Invalid month format, use YYYY-MM", 400);
 92	            }
 93	
 94	            StringBuilder csv = new StringBuilder();
 95	            csv.append("reservation,room,check_in,check_out,status,amount\n");
 96	
 97	            List<Reservation> reservations = reservationService.getReservationsByMonthWithPayment(month);
 98	            BigDecimal total = BigDecimal.ZERO;
 99	
100	            for (Reservation res : reservations) {
101	                BigDecimal money = res.getAmountPaid();
102	                if (res.getRefund() != null) {
103	                    money = money.subtract(res.getRefund());
104	                }
105	
106	                csv.append(res.getId()).append(",");
107	                csv.append(res.getRoomNumber()).append(",");
108	                csv.append(res.getCheckIn()).append(",");
109	                csv.append(res.getCheckOut()).append(",");
110	                csv.append(res.getStatus()).append(",");
111	                csv.append(formatAmount(money)).append("\n");
112	
113	                total = total.add(money);
114	            }
115	
116	            csv.append("total,,,,").append(formatAmount(total));
117	
118	            ctx.contentType("text/csv;charset=utf-8");
119	            ctx.result(csv.toString());
120	        } catch (ApiException e) {
121	            ctx.status(e.getStatusCode());
122	            ctx.json(new ErrorResponse(e.getCode(), e.getMessage()));
123	        } catch (Exception e) {
124	            ctx.status(400);
125	            ctx.json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
126	        }
127	    }
