     8	public class MoneyUtilsTest {
     9	    @Test
    10	    public void testRoundHalfEven() {
    11	        // Test rounding to nearest even (banker's rounding)
    12	        assertEquals(new BigDecimal("2.50"), MoneyUtils.round(new BigDecimal("2.500")));
    13	        assertEquals(new BigDecimal("2.50"), MoneyUtils.round(new BigDecimal("2.504")));
    14	        assertEquals(new BigDecimal("2.51"), MoneyUtils.round(new BigDecimal("2.506")));
    15	    }
    16	
    17	    @Test
    18	    public void testFormatBRL() {
    19	        String formatted = MoneyUtils.formatBRL(new BigDecimal("1234.56"));
    20	        assertEquals("R$ 1.234,56", formatted);
    21	    }
    22	
    23	    @Test
    24	    public void testCalculationExample() {
    25	        // Example: 10/07/2027 a 12/07/2027 (2 nights), STANDARD (249.90), high season
    26	        // Night 1 (10/07): 249.90 * 1.20 = 299.88
    27	        // Night 2 (11/07): 249.90 * 1.20 = 299.88
    28	        // Total: 599.76
    29	        BigDecimal rate = new BigDecimal("249.90");
    30	        BigDecimal highSeasonRate = rate.multiply(new BigDecimal("1.20"));
    31	        highSeasonRate = MoneyUtils.round(highSeasonRate);
    32	
    33	        BigDecimal total = highSeasonRate.add(highSeasonRate);
    34	        total = MoneyUtils.round(total);
    35	
    36	        assertEquals(new BigDecimal("299.88"), highSeasonRate);
    37	        assertEquals(new BigDecimal("599.76"), total);
    38	    }
    39	}
